/**
 * The single implementation of the invariants that decide whether a worksheet
 * state/structure is renderable and persistable:
 *
 * - `rowCount` / `colCount` are positive integers (the grid needs at least one
 *   row and one column, and a sparse cell table cannot express the structure);
 * - every cell of `cells` lies inside the reported structure (`PUT .../cells`
 *   shares the same bound through `assertCellWithinStructure`);
 * - the sub-issue A import footprint (`minRows` / `minCols`, nullable and
 *   owned by the CSV-import writer) never exceeds the structure it reports.
 *
 * Extracted from the inline checks in `importWorksheetState` with unchanged
 * semantics (contract v1.3, Issue #1 thread 1 comment #57 §2), so the state
 * endpoint and the CSV import writer validate through one code path instead of
 * two drifting copies.
 *
 * @param {object} state
 * @param {number} state.rowCount
 * @param {number} state.colCount
 * @param {CellEntry[] | undefined} [state.cells] `undefined` = not part of this write
 * @param {number | null | undefined} [state.minRows] `undefined`/`null` = no footprint reported
 * @param {number | null | undefined} [state.minCols]
 * @returns {void}
 */
export function assertWorksheetStateValid({ rowCount, colCount, cells, minRows, minCols }) {
  if (!Number.isInteger(rowCount) || rowCount < 1) {
    throw invalidBody('rowCount must be a positive integer');
  }
  if (!Number.isInteger(colCount) || colCount < 1) {
    throw invalidBody('colCount must be a positive integer');
  }
  if (minRows !== undefined && minRows !== null) {
    if (!Number.isInteger(minRows) || minRows < 0) {
      throw invalidBody('minRows must be a non-negative integer');
    }
    if (minRows > rowCount) {
      throw invalidBody(`minRows must not exceed rowCount (${rowCount})`);
    }
  }
  if (minCols !== undefined && minCols !== null) {
    if (!Number.isInteger(minCols) || minCols < 0) {
      throw invalidBody('minCols must be a non-negative integer');
    }
    if (minCols > colCount) {
      throw invalidBody(`minCols must not exceed colCount (${colCount})`);
    }
  }
  if (cells === undefined) return;
  if (!Array.isArray(cells)) throw invalidBody('cells must be an array');
  for (const entry of cells) {
    const [row, col] = entry;
    if (!Number.isInteger(row) || row < 0 || !Number.isInteger(col) || col < 0) {
      throw invalidBody('Cell coordinates must be non-negative integers');
    }
    assertCellWithinStructure(row, col, rowCount, colCount);
  }
}
