 * @param {string} worksheetId
 */
function sheetCells(db, worksheetId) {
  return /** @type {{ row: number, col: number, raw: string }[]} */ (
    db
      .prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ? ORDER BY row, col')
      .all(worksheetId)
  );
}

/**
 * @param {import('./db.js').Db} db
 * @param {string} worksheetId
 * @param {{ row: number, col: number, raw: string }[]} cells
 */
function setCells(db, worksheetId, cells) {
  db.prepare('DELETE FROM cells WHERE worksheet_id = ?').run(worksheetId);
  const insert = db.prepare('INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)');
  for (const cell of cells) insert.run(worksheetId, cell.row, cell.col, cell.raw);
}

