describe('shared worksheet-state validation helper (contract v1.3, Issue #1 comment #57 §2)', () => {
  /**
   * The first two rows are exactly the checks that used to be inline in
   * `importWorksheetState`; the same inputs must produce the same message and
   * error code through both the helper and the state endpoint (extraction
   * equivalence).
   */
  const invalidStates = [
    [{ rowCount: 0, colCount: 3 }, 'rowCount must be a positive integer'],
    [{ rowCount: 2.5, colCount: 3 }, 'rowCount must be a positive integer'],
    [{ rowCount: 6, colCount: 0 }, 'colCount must be a positive integer'],
    [
      { rowCount: 6, colCount: 26, cells: [[6, 0, 'x']] },
      'Cell 6,0 is outside the worksheet structure (6x26)',
    ],
    [
      { rowCount: 6, colCount: 26, cells: [[0, -1, 'x']] },
      'Cell coordinates must be non-negative integers',
    ],
    [{ rowCount: 6, colCount: 26, cells: 'nope' }, 'cells must be an array'],
  ];

  it('keeps the pre-extraction rejection messages for dimension and cell violations', () => {
    for (const [state, message] of invalidStates) {
      expect(() => assertWorksheetStateValid(/** @type {any} */ (state))).toThrowError(
        expect.objectContaining({ code: 'INVALID_BODY', message }),
      );
    }
  });

  it('rejects the same states through the state endpoint (never a silent write)', async () => {
    const app = appFor(freshDb());
    const before = await snapshot(app);
    for (const [state, message] of invalidStates) {
      const res = await request(app)
        .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
        .send(state);
      expect(res.status).toBe(400);
      expect(res.body.error).toEqual({ code: 'INVALID_BODY', message });
    }
    const after = await snapshot(app);
    expect(after.sheet).toEqual(before.sheet);
  });

  it('accepts a state at the reported structure boundary', () => {
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, cells: [[5, 25, 'corner']] }),
    ).not.toThrow();
  });

  it('validates the import footprint as a lower bound of the reported structure', () => {
    expect(() => assertWorksheetStateValid({ rowCount: 6, colCount: 26, minRows: 6 })).not.toThrow();
    expect(() => assertWorksheetStateValid({ rowCount: 6, colCount: 26, minCols: 26 })).not.toThrow();
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, minRows: 7 }),
    ).toThrowError(
      expect.objectContaining({
        code: 'INVALID_BODY',
        message: 'minRows must not exceed the reported structure (6)',
      }),
    );
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, minCols: 27 }),
    ).toThrowError(
      expect.objectContaining({
        code: 'INVALID_BODY',
        message: 'minCols must not exceed the reported structure (26)',
      }),
    );
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, minRows: -1 }),
    ).toThrowError(expect.objectContaining({ message: 'minRows must be a non-negative integer' }));
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, minCols: 1.5 }),
    ).toThrowError(expect.objectContaining({ message: 'minCols must be a non-negative integer' }));
  });

  it('treats an absent footprint as nothing to validate (undefined = don\'t change, PR #8)', () => {
    expect(() =>
      assertWorksheetStateValid({ rowCount: 6, colCount: 26, minRows: undefined, minCols: null }),
    ).not.toThrow();
  });

  it('gates the footprint on the state endpoint before anything is written', async () => {
    const app = appFor(freshDb());
    const before = await snapshot(app);
    const res = await request(app)
      .put(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/state`)
      .send({ rowCount: 2, colCount: 2, cells: [[0, 0, 'Changed']], minRows: 3 });
    expect(res.status).toBe(400);
    expect(res.body.error).toEqual({
      code: 'INVALID_BODY',
      message: 'minRows must not exceed the reported structure (2)',
    });
    const after = await snapshot(app);
    expect(after.sheet).toEqual(before.sheet);
  });
});

