import { useState } from 'react';
import type { WorksheetSnapshot } from '../../../shared/types';
import { Menu } from './Menu';
import { DeleteWorksheetDialog, RenameWorksheetDialog } from './WorksheetDialogs';

export interface WorksheetTabsProps {
  worksheets: WorksheetSnapshot[];
  activeWorksheetId: string;
  onSelect: (worksheetId: string) => void;
  onAdd: () => void;
  onRename: (worksheetId: string, name: string) => Promise<void>;
  onDelete: (worksheetId: string) => Promise<void>;
  onError: (message: string) => void;
}

/**
 * Bottom worksheet tab bar (REQ-2-1-*): "Add worksheet" button, ARIA `tab` per
 * worksheet, a "Worksheet options for <name>" button per tab whose menu offers
 * "Rename"/"Delete" as ARIA `menuitem`s, and the two named dialogs. Tabs keep
 * the accessible name of the worksheet itself; the options button is a sibling
 * so it never leaks into the tab name.
 */
export function WorksheetTabs({
  worksheets,
  activeWorksheetId,
  onSelect,
  onAdd,
  onRename,
  onDelete,
  onError,
}: WorksheetTabsProps) {
  const [menuForId, setMenuForId] = useState<string | null>(null);
  const [renameTarget, setRenameTarget] = useState<WorksheetSnapshot | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<WorksheetSnapshot | null>(null);

  const requestDelete = (worksheet: WorksheetSnapshot) => {
    if (worksheets.length <= 1) {
      // REQ-2-1-4: the last worksheet is not deletable; no confirmation dialog.
      onError('A workbook must contain at least one worksheet');
      return;
    }
    setDeleteTarget(worksheet);
  };

  return (
    <>
      <div
        role="tablist"
        aria-label="Worksheets"
        className="flex items-center gap-2 border-t-1 border-sheet-border bg-sheet-header px-2 py-1"
      >
        <button
          type="button"
          aria-label="Add worksheet"
          onClick={onAdd}
          className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-lg leading-none text-sheet-muted hover:bg-#e8eaed"
        >
          +
        </button>
        <div className="flex items-center gap-1">
          {worksheets.map((worksheet) => {
            const active = worksheet.id === activeWorksheetId;
            const menuOpen = menuForId === worksheet.id;
            return (
              <div key={worksheet.id} className="relative flex items-center">
                <button
                  type="button"
                  role="tab"
                  id={`worksheet-tab-${worksheet.id}`}
                  aria-selected={active}
                  aria-controls="worksheet-grid-panel"
                  onClick={() => onSelect(worksheet.id)}
                  className={
                    'rounded-t px-3 py-1 text-sm ' +
                    (active
                      ? 'bg-white font-medium text-sheet-accent shadow-sm'
                      : 'text-sheet-muted hover:bg-#e8eaed')
                  }
                >
                  {worksheet.name}
                </button>
                <button
                  type="button"
                  aria-label={`Worksheet options for ${worksheet.name}`}
                  aria-haspopup="menu"
                  aria-expanded={menuOpen}
                  onClick={() => setMenuForId(menuOpen ? null : worksheet.id)}
                  className={
                    'ml-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-xs ' +
                    (active ? 'text-sheet-accent hover:bg-#e8f0fe' : 'text-sheet-muted hover:bg-#e8eaed')
                  }
                >
                  ▾
                </button>
                {menuOpen ? (
                  <Menu
                    label={`Worksheet options for ${worksheet.name}`}
                    onClose={() => setMenuForId(null)}
                    className="absolute bottom-full left-0 mb-1"
                    items={[
                      {
                        label: 'Rename',
                        onSelect: () => setRenameTarget(worksheet),
                      },
                      {
                        label: 'Delete',
                        onSelect: () => requestDelete(worksheet),
                      },
                    ]}
                  />
                ) : null}
              </div>
            );
          })}
        </div>
      </div>

      {renameTarget ? (
        <RenameWorksheetDialog
          initialName={renameTarget.name}
          onClose={() => setRenameTarget(null)}
          onSave={async (name) => {
            await onRename(renameTarget.id, name);
            setRenameTarget(null);
          }}
        />
      ) : null}

      {deleteTarget ? (
        <DeleteWorksheetDialog
          worksheetName={deleteTarget.name}
          onClose={() => setDeleteTarget(null)}
          onConfirm={() => {
            const target = deleteTarget;
            setDeleteTarget(null);
            void onDelete(target.id);
          }}
        />
      ) : null}
    </>
  );
}

import { useEffect, useRef, type CSSProperties } from 'react';

export interface MenuEntry {
  /** Visible label and accessible name of the `menuitem`. */
  label: string;
  onSelect: () => void;
}

export interface MenuProps {
  /** Accessible name of the `role="menu"` container. */
  label: string;
  /** Commands in order; `'separator'` renders an ARIA separator. */
  items: (MenuEntry | 'separator')[];
  onClose: () => void;
  className?: string;
  style?: CSSProperties;
}

/**
 * Small popup menu used by the worksheet tab options and the row/column header
 * context menus. Commands are `role="menuitem"` per the shared contract §3.
 * Closes on command selection, Escape, an outside pointer press or scroll, so a
 * stale menu can never cover the grid.
 */
export function Menu({ label, items, onClose, className = '', style }: MenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onCloseRef.current();
    };
    const handlePointerDown = (event: MouseEvent) => {
      const target = event.target;
      if (ref.current && target instanceof Node && ref.current.contains(target)) return;
      onCloseRef.current();
    };
    const handleScroll = () => onCloseRef.current();
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('mousedown', handlePointerDown, true);
    window.addEventListener('scroll', handleScroll, true);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('mousedown', handlePointerDown, true);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, []);

  return (
    <div
      ref={ref}
      role="menu"
      aria-label={label}
      style={style}
      className={
        'z-50 flex min-w-44 flex-col rounded-lg border-1 border-sheet-border bg-white py-1 shadow-lg ' +
        className
      }
    >
      {items.map((item, index) =>
        item === 'separator' ? (
          // eslint-disable-next-line react/no-array-index-key
          <div key={`separator-${index}`} role="separator" className="my-1 border-t-1 border-sheet-border" />
        ) : (
          <button
            key={item.label}
            type="button"
            role="menuitem"
            onClick={() => {
              onClose();
              item.onSelect();
            }}
            className="px-3 py-1.5 text-left text-sm text-sheet-text hover:bg-#f1f3f4"
          >
            {item.label}
          </button>
        ),
      )}
    </div>
  );
}
