 * @param {Db} db
 * @param {string} workbookId
 * @param {unknown} rawName
 * @returns {WorkbookSnapshot}
 */
export function createWorksheet(db, workbookId, rawName) {
  const wb = getWorkbookRow(db, workbookId);
  if (!wb) throw notFound('Workbook not found');
  const id = newId('ws');
  const at = nowIso();
  db.transaction(() => {
    let name;
    if (rawName === undefined || rawName === null) {
      name = deriveWorksheetName(db, workbookId);
    } else {
      if (typeof rawName !== 'string') throw invalidBody('Worksheet name must be a string');
      name = rawName.trim();
      if (!name) throw validationError('Worksheet name cannot be empty');
      assertWorksheetNameAvailable(db, workbookId, null, name);
    }
    const maxPosition = /** @type {{ p: number }} */ (
      db
        .prepare('SELECT COALESCE(MAX(position), -1) AS p FROM worksheets WHERE workbook_id = ?')
        .get(workbookId)
    ).p;
    db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(workbookId);
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      id,
      workbookId,
      name,
      maxPosition + 1,
      DEFAULT_ROW_COUNT,
      DEFAULT_COL_COUNT,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
    touchWorkbook(db, workbookId, at);
  })();
