 */
export function deleteWorksheet(db, ws) {
  const workbookId = ws.workbook_id;
  const at = nowIso();
  db.transaction(() => {
    const siblings = /** @type {{ id: string }[]} */ (
      db
        .prepare('SELECT id FROM worksheets WHERE workbook_id = ? ORDER BY position, rowid')
        .all(workbookId)
    );
    if (siblings.length <= 1) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'A workbook must contain at least one worksheet',
      );
    }
    const dependency = db
      .prepare('SELECT id FROM pivots WHERE source_worksheet_id = ? LIMIT 1')
      .get(ws.id);
    if (dependency) {
      throw new ApiError(
        409,
        'VALIDATION_ERROR',
        'Please delete or rebuild dependent pivot tables first',
      );
    }
    const index = siblings.findIndex((sibling) => sibling.id === ws.id);
    const wasActive = ws.last_active === 1;
    db.prepare('DELETE FROM worksheets WHERE id = ?').run(ws.id);
    if (wasActive) {
      const neighbor = siblings[index + 1] ?? siblings[index - 1];
      db.prepare('UPDATE worksheets SET last_active = 0 WHERE workbook_id = ?').run(workbookId);
      db.prepare('UPDATE worksheets SET last_active = 1 WHERE id = ?').run(neighbor.id);
    }
    touchWorkbook(db, workbookId, at);
  })();
  const snapshot = getWorkbookSnapshot(db, workbookId);
  if (!snapshot) throw notFound('Workbook not found');
  return snapshot;
}

