import { expect, test, type APIRequestContext, type Page } from '@playwright/test';

/**
 * Sub-issue B acceptance (Issue #4 REQ-2-1-1…2-2-2): worksheet lifecycle and
 * row/column structure driven through the visible controls only, locating
 * everything by accessible name (`exact: true` / `[aria-label]` per contract
