interface WorksheetSnapshot {
  id: string;
  name: string;
  position: number;
  isActive: boolean;
  rowCount: number;
  colCount: number;
  cells: [number, number, string][];
}

interface WorkbookSnapshot {
  id: string;
  name: string;
  worksheets: WorksheetSnapshot[];
}

async function createWorkbook(request: APIRequestContext, name: string): Promise<WorkbookSnapshot> {
  const res = await request.post('/api/workbooks', { data: { name } });
  expect(res.ok()).toBeTruthy();
  return (await res.json()) as WorkbookSnapshot;
}

async function putCells(
  request: APIRequestContext,
  workbookId: string,
  worksheetId: string,
  changes: { row: number; col: number; raw: string }[],
): Promise<void> {
  const res = await request.put(`/api/workbooks/${workbookId}/worksheets/${worksheetId}/cells`, {
    data: { changes },
  });
  expect(res.ok()).toBeTruthy();
}

async function openWorkbook(page: Page, workbookId: string): Promise<void> {
  await page.goto(`/workbook/${workbookId}`);
  await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
}

async function openTabOptions(page: Page, worksheetName: string): Promise<void> {
  await page.getByRole('button', { name: `Worksheet options for ${worksheetName}` }).click();
}

