import type { ReactNode } from 'react';

export interface ErrorBannerProps {
  message: string | null;
  onDismiss?: () => void;
}

/** Visible, announced error surface for failed commits and load errors. */
export function ErrorBanner({ message, onDismiss }: ErrorBannerProps): ReactNode {
  if (!message) return null;
  return (
    <div
      role="alert"
      className="flex items-center justify-between gap-4 border-b-1 border-#f5c6c2 bg-#fce8e6 px-3 py-2 text-sm text-sheet-danger"
    >
      <span>{message}</span>
      {onDismiss ? (
        <button type="button" onClick={onDismiss} className="text-sheet-danger underline">
          Dismiss
        </button>
      ) : null}
    </div>
  );
}
