  page,
  request,
}) => {
  const workbook = await createWorkbook(request, 'Failed Add Test');
  await openWorkbook(page, workbook.id);
  await expect(page.getByRole('tab')).toHaveCount(1);

  // REQ-2-1-1: a failed addition shows an error, adds no tab and leaves the
  // existing worksheets (and their data) unchanged. Only the creation call
  // fails; the failure is injected at the network boundary.
  await page.route('**/api/workbooks/*/worksheets', async (route) => {
    if (route.request().method() !== 'POST') {
      await route.continue();
      return;
    }
    await route.fulfill({
      status: 500,
      contentType: 'application/json',
      body: JSON.stringify({
        error: { code: 'INTERNAL_ERROR', message: 'Worksheet could not be added' },
      }),
    });
  });

  await page.getByRole('button', { name: 'Add worksheet' }).click();
  await expect(page.getByRole('alert')).toContainText('Worksheet could not be added');
