  await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveAttribute(
    'aria-selected',
    'true',
  );

  // Nothing was persisted: a refresh still shows the single worksheet.
  await page.reload();
  await expect(page.getByRole('grid', { name: 'Worksheet grid' })).toBeVisible();
  await expect(page.getByRole('tab')).toHaveCount(1);
});

